-- Public reviewer SQL: supply review_cohort(stay_id,hadm_id,subject_id,t0).
-- The Python runner binds the same authorized keys with a VALUES CTE instead.
WITH keys(stay_id,hadm_id,subject_id,t0) AS (SELECT stay_id,hadm_id,subject_id,t0 FROM review_cohort), c AS MATERIALIZED (SELECT k.*,i.intime,i.outtime,greatest(i.intime,k.t0-interval '24 hour') ws FROM keys k JOIN mimiciv_icu.icustays i USING(stay_id)) SELECT c.stay_id,x.charttime,x.urineoutput_6hr,x.urineoutput_12hr,x.urineoutput_24hr,x.uo_tm_6hr,x.uo_tm_12hr,x.uo_tm_24hr FROM c JOIN mimiciv_derived.urine_output_rate x ON x.stay_id=c.stay_id AND x.charttime>=c.ws AND x.charttime<c.t0;